function syncManifestUrl(){const form=document.getElementById('settingsForm'),output=document.getElementById('manifestUrl');if(!form||!output)return;const base=String(form.elements.baseUrl?.value||state.settings.baseUrl||'').trim().replace(/\/+$/,'');output.value=base?base+'/manifest.json':''}
function refreshBranding(){const url=brandingIconUrl(),name=state.settings.addonName||'Nuvi-Flow';for(const id of ['sidebarBrandIcon','addonIconPreview']){const image=document.getElementById(id);if(image&&image.getAttribute('src')!==url){image.src=url;image.alt=name}}const brandName=document.getElementById('brandName');if(brandName)brandName.textContent=name;document.title=name}
async function uploadAddonIcon(file){if(!file)return;if(file.size>2*1024*1024){toast('Icon must be 2 MB or smaller');return}const input=document.getElementById('addonIconFile'),body=new FormData();body.append('icon',file);try{const data=await api('/admin/api/branding/icon',{method:'POST',body});if(data.settings)state.settings=data.settings;refreshBranding();toast('Addon icon updated')}catch(err){toast(err.message||'Icon upload failed')}finally{if(input)input.value=''}}
async function removeAddonIconNow(button){if(!window.confirm('Remove the custom icon and restore the Nuvi-Flow default?'))return;const original=button.textContent;button.disabled=true;button.textContent='Removing…';try{const data=await api('/admin/api/branding/icon',{method:'DELETE'});if(data.settings)state.settings=data.settings;refreshBranding();toast('Default icon restored')}catch(err){toast(err.message||'Could not remove icon')}finally{button.disabled=false;button.textContent=original}}
function duration(seconds){if(!seconds)return '—';const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60),s=Math.round(seconds%60);return h?h+'h '+m+'m':m?m+'m '+s+'s':s+'s'}
function bitrate(value){return value?((Number(value)/1000000).toFixed(Number(value)>=10000000?0:1)+' Mbps'):'Unknown'}
function statusBadge(file){const cls=file.status==='matched'?'good':file.status==='error'?'danger':'warn';const label=file.status==='matched'&&file.confidence!=null?Math.round(file.confidence*100)+'% match':file.status;return '<span class="badge '+cls+'">'+esc(label)+'</span>'}
function listRow(file,action='Details'){return '<div class="list-row"><div class="file-icon">'+(file.libraryType==='movie'?'MOV':'TV')+'</div><div><div class="list-title">'+esc(file.displayTitle||file.parsedTitle||file.relativePath)+'</div><div class="list-meta">'+esc(file.relativePath)+' · '+esc(file.quality||file.height&&file.height+'p'||'Unknown quality')+'</div></div><button class="btn small" type="button" data-file="'+esc(file.id)+'">'+action+'</button></div>'}
function render(){const c=state.counts;document.getElementById('stats').innerHTML=[['Movies',c.movies||0,''],['Series',c.series||0,''],['Episodes',c.episodes||0,''],['Unmatched',c.unmatched||0,'alert'],['Errors',c.errors||0,'alert']].map(x=>'<div class="stat '+x[2]+'"><span>'+x[0]+'</span><strong>'+x[1]+'</strong></div>').join('');document.getElementById('recentList').innerHTML=state.recent.length?state.recent.map(f=>listRow(f)).join(''):'<div class="empty">No media has been scanned yet.</div>';const attention=state.files.filter(f=>f.status==='unmatched'||f.status==='error'||(f.confidence!=null&&f.confidence<.86));document.getElementById('attentionList').innerHTML=attention.length?attention.slice(0,5).map(f=>listRow(f,'Review')).join(''):'<div class="empty">Everything looks tidy.</div>';document.getElementById('reviewList').innerHTML=attention.length?attention.map(f=>listRow(f,'Review')).join(''):'<div class="empty">No files need review.</div>';renderLibrary();document.getElementById('scanLogs').innerHTML=state.logs.length?state.logs.map(l=>'<div class="log"><span>'+new Date(l.startedAt).toLocaleString()+'</span><span class="badge '+(l.status==='completed'?'good':'warn')+'">'+esc(l.status)+'</span><span>'+esc(l.mode)+' · '+l.discovered+' found · '+l.processed+' processed · '+l.matched+' matched · '+l.errors+' errors</span></div>').join(''):'<div class="empty">No scans have run yet.</div>';const latest=state.logs[0];document.getElementById('lastScan').textContent=latest?'Last scan '+new Date(latest.startedAt).toLocaleString()+' · '+latest.status:'No scans have run yet';renderRequests();fillSettings()}
function requestMediaLabel(request){let label=request.title||request.stremioId||'Unknown media';if(request.mediaType==='series'&&request.season!=null&&request.episode!=null)label+=' · S'+String(request.season).padStart(2,'0')+'E'+String(request.episode).padStart(2,'0');return label}
function requestStatusBadge(request){const cls=request.status==='available'?'good':request.status==='failed'?'danger':'warn',label=request.status==='available'?'Added':request.status;return '<span class="badge '+cls+'">'+esc(label)+'</span>'}
function renderRequests(){const rows=state.requests||[],body=document.getElementById('requestRows');if(!body)return;body.innerHTML=rows.map(request=>'<tr><td><strong>'+esc(requestMediaLabel(request))+'</strong><div class="list-meta">'+esc(request.imdbId?'IMDb '+request.imdbId:request.tvdbId?'TVDB '+request.tvdbId:'')+'</div></td><td>'+esc(String(request.backend||'').toUpperCase())+'</td><td>'+requestStatusBadge(request)+'</td><td>'+esc(request.attempts??0)+'</td><td>'+esc(request.message||'—')+'</td><td>'+esc(request.updatedAt?new Date(request.updatedAt).toLocaleString():'—')+'</td><td>'+(request.status==='failed'?'<button class="btn small" type="button" data-retry-request="'+esc(request.id)+'">Retry</button>':'')+'</td></tr>').join('')||'<tr><td colspan="7"><div class="empty">No automatic requests have been made yet.</div></td></tr>'}
async function retryRequest(id,button){const original=button.textContent;button.disabled=true;button.textContent='Retrying…';try{await api('/admin/api/requests/'+encodeURIComponent(id)+'/retry',{method:'POST'});toast('Request retry started');await load()}catch(err){toast(err.message||'Retry failed');button.disabled=false;button.textContent=original}}
function renderLibrary(){const term=(document.getElementById('librarySearch').value||'').toLowerCase(),type=document.getElementById('libraryType').value;const rows=state.files.filter(f=>(!type||f.libraryType===type)&&(!term||(f.parsedTitle||'').toLowerCase().includes(term)||f.relativePath.toLowerCase().includes(term)));document.getElementById('libraryRows').innerHTML=rows.map(f=>'<tr><td><strong>'+esc(f.displayTitle||f.parsedTitle||'Unknown')+'</strong></td><td>'+esc(f.libraryType)+'</td><td>'+esc(f.relativePath)+'</td><td>'+esc(f.quality||f.height&&f.height+'p'||'—')+'</td><td>'+duration(f.durationSeconds)+'</td><td>'+statusBadge(f)+'</td><td><button class="btn small" type="button" data-file="'+esc(f.id)+'">Open</button></td></tr>').join('')||'<tr><td colspan="7"><div class="empty">No files match this filter.</div></td></tr>'}
function setSelectValue(select,value,label){if(!select)return;const stringValue=String(value??'');if(stringValue&&!Array.from(select.options).some(option=>option.value===stringValue)){const option=document.createElement('option');option.value=stringValue;option.textContent=label||stringValue;select.appendChild(option)}select.value=stringValue}
function populateIntegrationSelect(select,items,currentValue,{emptyValue='',emptyLabel='Not selected',valueKey='id',labelKey='name'}={}){if(!select)return;const wanted=String(currentValue??select.value??emptyValue);select.innerHTML='';const empty=document.createElement('option');empty.value=emptyValue;empty.textContent=emptyLabel;select.appendChild(empty);for(const item of items||[]){const option=document.createElement('option');option.value=String(item[valueKey]);option.textContent=String(item[labelKey]??item[valueKey]);if(item.accessible===false)option.textContent+=' (unavailable)';select.appendChild(option)}if(wanted&&Array.from(select.options).some(option=>option.value===wanted)){select.value=wanted}else if(wanted&&wanted!==emptyValue){const option=document.createElement('option');option.value=wanted;option.textContent=wanted+' (saved, not returned by server)';select.appendChild(option);select.value=wanted}else select.value=emptyValue}
function applyIntegrationData(service,data){const form=document.getElementById('settingsForm');if(!form)return;if(service==='radarr'){populateIntegrationSelect(form.elements.radarrRootFolderPath,data.rootFolders,form.elements.radarrRootFolderPath.value,{valueKey:'path',labelKey:'path'});populateIntegrationSelect(form.elements.radarrQualityProfileId,data.qualityProfiles,form.elements.radarrQualityProfileId.value,{emptyValue:'0',valueKey:'id',labelKey:'name'})}else{populateIntegrationSelect(form.elements.sonarrRootFolderPath,data.rootFolders,form.elements.sonarrRootFolderPath.value,{valueKey:'path',labelKey:'path'});populateIntegrationSelect(form.elements.sonarrAnimeRootFolderPath,data.rootFolders,form.elements.sonarrAnimeRootFolderPath.value,{valueKey:'path',labelKey:'path'});populateIntegrationSelect(form.elements.sonarrQualityProfileId,data.qualityProfiles,form.elements.sonarrQualityProfileId.value,{emptyValue:'0',valueKey:'id',labelKey:'name'});populateIntegrationSelect(form.elements.sonarrAnimeQualityProfileId,data.qualityProfiles,form.elements.sonarrAnimeQualityProfileId.value,{emptyValue:'0',emptyLabel:'Use normal TV quality profile',valueKey:'id',labelKey:'name'})}}
async function loadSavedIntegrationOptions(service){const form=document.getElementById('settingsForm');if(!form)return;const configured=service==='radarr'?state.settings.radarrConfigured:state.settings.sonarrConfigured;if(!configured)return;const url=form.elements[service+'Url']?.value?.trim()||'';try{const data=await api('/admin/api/integrations/'+service+'/test',{method:'POST',body:JSON.stringify({url})});applyIntegrationData(service,data)}catch(err){const status=document.getElementById(service+'Status');if(status){status.textContent='API key saved. Could not load profile names: '+(err.message||'connection failed');status.className='integration-status warn'}}}
async function testIntegration(service,button){const form=document.getElementById('settingsForm'),name=service==='radarr'?'Radarr':'Sonarr',status=document.getElementById(service+'Status'),url=form.elements[service+'Url']?.value?.trim()||'',apiKey=form.elements[service+'ApiKey']?.value?.trim()||'',original=button.textContent;button.disabled=true;button.textContent='Testing…';status.textContent='Testing connection…';status.className='integration-status';try{const data=await api('/admin/api/integrations/'+service+'/test',{method:'POST',body:JSON.stringify({url,apiKey})});applyIntegrationData(service,data);const roots=(data.rootFolders||[]).length,profiles=(data.qualityProfiles||[]).length;status.textContent='Connected to '+(data.instanceName||name)+(data.version?' · v'+data.version:'')+'. '+roots+' root folder'+(roots===1?'':'s')+' and '+profiles+' quality profile'+(profiles===1?'':'s')+' found.';status.className='integration-status good'}catch(err){status.textContent=err.message||name+' connection failed.';status.className='integration-status danger'}finally{button.disabled=false;button.textContent=original}}
function syncAnimeRootState(){const form=document.getElementById('settingsForm');if(!form)return;const enabled=form.elements.sonarrSeparateAnimeRoot?.value==='true';if(form.elements.sonarrAnimeRootFolderPath)form.elements.sonarrAnimeRootFolderPath.disabled=!enabled}
function fillSettings(force=false){if(settingsDirty&&!force)return;const form=document.getElementById('settingsForm'),s=state.settings;for(const name of ['addonName','baseUrl','moviesPath','tvPath','animePath','scanIntervalMinutes','minimumFileSizeMb','streamTokenExpiryHours','longLivedStreamTokens','adminUsername','autoRequestEnabled','radarrEnabled','radarrUrl','sonarrEnabled','sonarrUrl','sonarrSeparateAnimeRoot'])if(form.elements[name])form.elements[name].value=String(s[name]??'');setSelectValue(form.elements.radarrRootFolderPath,s.radarrRootFolderPath,s.radarrRootFolderPath);setSelectValue(form.elements.radarrQualityProfileId,s.radarrQualityProfileId,s.radarrQualityProfileId?'Profile #'+s.radarrQualityProfileId:'Not selected');setSelectValue(form.elements.sonarrRootFolderPath,s.sonarrRootFolderPath,s.sonarrRootFolderPath);setSelectValue(form.elements.sonarrAnimeRootFolderPath,s.sonarrAnimeRootFolderPath,s.sonarrAnimeRootFolderPath);setSelectValue(form.elements.sonarrQualityProfileId,s.sonarrQualityProfileId,s.sonarrQualityProfileId?'Profile #'+s.sonarrQualityProfileId:'Not selected');setSelectValue(form.elements.sonarrAnimeQualityProfileId,s.sonarrAnimeQualityProfileId,s.sonarrAnimeQualityProfileId?'Profile #'+s.sonarrAnimeQualityProfileId:'Use normal TV quality profile');document.getElementById('tmdbStatus').textContent=s.metadataProvider||'Automatic metadata is active.';const radarrStatus=document.getElementById('radarrStatus');radarrStatus.textContent=s.radarrConfigured?'API key saved.':'No API key saved.';radarrStatus.className='integration-status '+(s.radarrConfigured?'good':'warn');const sonarrStatus=document.getElementById('sonarrStatus');sonarrStatus.textContent=s.sonarrConfigured?'API key saved.':'No API key saved.';sonarrStatus.className='integration-status '+(s.sonarrConfigured?'good':'warn');if(form.elements.radarrApiKey)form.elements.radarrApiKey.value='';if(form.elements.sonarrApiKey)form.elements.sonarrApiKey.value='';syncAnimeRootState();refreshBranding();syncManifestUrl()}
async function load(){const request=++stateRequest,[data,requestData]=await Promise.all([api('/admin/api/state'),api('/admin/api/requests')]);if(request!==stateRequest)return;state={...data,requests:requestData.requests||[]};render()}
function switchView(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'})}
